<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { categoryLabel, demoSubmissions, projects, type Category, type CivicProject, type CivicSubmission, type SubmissionType } from './domain/demoData'
import { findMatches } from './domain/matching'
import { migrateLegacyReportOwners } from './domain/reportVisibility'

type Role = 'COMMUNITY_MEMBER' | 'GOVERNMENT_REVIEWER' | 'DEPARTMENT_OFFICIAL' | 'INVESTIGATOR' | 'AUDITOR' | 'ADMIN'
type Report = CivicSubmission & { ownerId?: string | null; matchCandidates: string[]; investigationType: 'COMMUNITY_NEED' | 'PROJECT_ACCOUNTABILITY' | null }
type Note = { id: string; reportId: string; text: string; author: string; date: string }
type Finding = Note & { classification: string }
type Action = { id: string; reportId: string; text: string; status: 'OPEN' | 'COMPLETE' }
type Review = { id: string; reportId: string; projectId: string; decision: 'CONFIRMED' | 'REJECTED'; reason: string }
const memberId = 'demo-community-member'
const roles: Role[] = ['COMMUNITY_MEMBER', 'GOVERNMENT_REVIEWER', 'DEPARTMENT_OFFICIAL', 'INVESTIGATOR', 'AUDITOR', 'ADMIN']
const role = ref<Role>('COMMUNITY_MEMBER')
const activePage = ref('My needs')
const activeReportId = ref<string | null>(null)
const search = ref('')
const statusFilter = ref('ALL')
const categoryFilter = ref('ALL')
const modalOpen = ref(false)
const notice = ref('')
const today = () => new Date().toISOString().slice(0, 10)
const seededReports: Report[] = demoSubmissions.map(item => ({ ...item, ownerId: null, matchCandidates: [...item.matches], investigationType: item.status === 'Under investigation' ? 'COMMUNITY_NEED' : item.status === 'Investigation opened' ? 'PROJECT_ACCOUNTABILITY' : null }))
function load<T>(key: string, fallback: T): T { try { const value = localStorage.getItem(key); return value ? JSON.parse(value) as T : fallback } catch { return fallback } }
const reports = ref<Report[]>(migrateLegacyReportOwners(load<Report[]>('civicproof-reports', seededReports), memberId))
const responses = ref<Note[]>(load('civicproof-responses', []))
const findings = ref<Finding[]>(load('civicproof-findings', []))
const actions = ref<Action[]>(load('civicproof-actions', []))
const reviews = ref<Review[]>(load('civicproof-reviews', []))
const reportDetail = computed(() => reports.value.find(report => report.id === activeReportId.value) ?? null)
const isCommunity = computed(() => role.value === 'COMMUNITY_MEMBER')
const ownReports = computed(() => reports.value.filter(report => report.ownerId === memberId))
const investigations = computed(() => reports.value.filter(report => report.investigationType))
const menu = computed(() => isCommunity.value ? ['My needs'] : role.value === 'GOVERNMENT_REVIEWER' ? ['Overview', 'All submissions', 'Projects', 'Match review'] : role.value === 'DEPARTMENT_OFFICIAL' ? ['Overview', 'All submissions', 'Responses'] : role.value === 'INVESTIGATOR' ? ['Overview', 'All submissions', 'Investigations'] : role.value === 'AUDITOR' ? ['Overview', 'All submissions', 'Projects', 'Investigations', 'Audit trail'] : ['Overview', 'All submissions', 'Projects', 'Match review', 'Investigations', 'Responses', 'Audit trail', 'Demo setup'])
const shownReports = computed(() => (isCommunity.value ? ownReports.value : reports.value).filter(report => `${report.title} ${report.area} ${categoryLabel(report.category)}`.toLowerCase().includes(search.value.toLowerCase())))
const shownProjects = computed(() => projects.filter(project => (statusFilter.value === 'ALL' || project.status === statusFilter.value) && (categoryFilter.value === 'ALL' || project.category === categoryFilter.value) && `${project.name} ${project.area}`.toLowerCase().includes(search.value.toLowerCase())))
const pendingMatches = computed(() => reports.value.flatMap(report => report.matchCandidates.filter(id => !reviews.value.some(review => review.reportId === report.id && review.projectId === id)).map(projectId => ({ report, project: projects.find(project => project.id === projectId) })).filter(item => item.project)))
const form = ref({ type: 'COMMUNITY_NEED' as SubmissionType, title: '', description: '', category: 'PUBLIC_LIGHTING' as Category, area: '', location: '' })
const responseText = ref('')
const findingText = ref('')
const findingClass = ref('HUMAN_REVIEWED')
const actionText = ref('')
const categoryOptions: Category[] = ['PUBLIC_LIGHTING', 'ROADS_TRANSPORT', 'WATER', 'SANITATION', 'STORMWATER', 'WASTE_MANAGEMENT', 'PUBLIC_FACILITIES']
const areas = [...new Set(projects.map(project => project.area))]

watch(reports, value => localStorage.setItem('civicproof-reports', JSON.stringify(value)), { deep: true })
watch(responses, value => localStorage.setItem('civicproof-responses', JSON.stringify(value)), { deep: true })
watch(findings, value => localStorage.setItem('civicproof-findings', JSON.stringify(value)), { deep: true })
watch(actions, value => localStorage.setItem('civicproof-actions', JSON.stringify(value)), { deep: true })
watch(reviews, value => localStorage.setItem('civicproof-reviews', JSON.stringify(value)), { deep: true })
watch(role, value => { activeReportId.value = null; search.value = ''; activePage.value = value === 'COMMUNITY_MEMBER' ? 'My needs' : 'Overview' })
function flash(message: string) { notice.value = message; window.setTimeout(() => { if (notice.value === message) notice.value = '' }, 5000) }
function navigate(page: string) { activePage.value = page; activeReportId.value = null; search.value = '' }
function openReport(report: Report) {
  if (isCommunity.value && report.ownerId !== memberId) return
  activeReportId.value = report.id
  // Overview's latest-submissions panel now opens the matching detail view.
  // Community members stay in their own-needs view; staff go to the staff list detail.
  activePage.value = isCommunity.value ? 'My needs' : 'All submissions'
}
function startReport() { modalOpen.value = true; activeReportId.value = null }
function submitReport() {
  if (form.value.title.trim().length < 3 || form.value.description.trim().length < 10 || !form.value.area || !form.value.location.trim()) { flash('Please complete each field. Title needs 3+ characters and description 10+ characters.'); return }
  const location = projects.find(project => project.area === form.value.area)!
  const matches = findMatches({ type: form.value.type, category: form.value.category, description: `${form.value.title} ${form.value.description}`, area: form.value.area, latitude: location.latitude, longitude: location.longitude }, projects)
  const report: Report = { id: `report-${crypto.randomUUID()}`, ownerId: memberId, type: form.value.type, title: form.value.title.trim(), description: form.value.description.trim(), category: form.value.category, area: form.value.area, latitude: location.latitude, longitude: location.longitude, createdAt: today(), status: matches.status === 'SUGGESTED' ? 'Match review' : 'Registered', matches: matches.candidates.map(item => item.project.id), matchCandidates: matches.candidates.map(item => item.project.id), synthetic: true, investigationType: null }
  reports.value.unshift(report); modalOpen.value = false; form.value = { type: 'COMMUNITY_NEED', title: '', description: '', category: 'PUBLIC_LIGHTING', area: '', location: '' }; openReport(report)
  flash(matches.status === 'NO_MATCH' ? 'Your need is registered. No relevant project was identified in available demo records.' : 'Your need is registered. Potential project matches are available to staff for review.')
}
function decideMatch(report: Report, project: CivicProject, decision: 'CONFIRMED' | 'REJECTED') {
  const reason = decision === 'CONFIRMED' ? 'Relationship confirmed for follow-up; this does not verify the report.' : 'Suggested relationship rejected; original report remains registered.'
  reviews.value.unshift({ id: crypto.randomUUID(), reportId: report.id, projectId: project.id, decision, reason })
  if (decision === 'CONFIRMED') { report.investigationType = 'PROJECT_ACCOUNTABILITY'; report.status = 'Investigation opened'; flash('Relationship confirmed for investigation. The underlying allegation remains unverified.') }
  else { report.matchCandidates = report.matchCandidates.filter(id => id !== project.id); report.matches = report.matches.filter(id => id !== project.id); if (!report.matchCandidates.length) report.status = 'Registered'; flash('Suggestion rejected; the community submission remains registered.') }
}
function addResponse(report: Report) { if (!responseText.value.trim()) return; responses.value.unshift({ id: crypto.randomUUID(), reportId: report.id, text: responseText.value.trim(), author: role.value.replaceAll('_', ' '), date: today() }); responseText.value = ''; if (report.status === 'Registered') report.status = 'Awaiting response'; flash('Response recorded in this local demo.') }
function addFinding(report: Report) { if (!findingText.value.trim()) return; findings.value.unshift({ id: crypto.randomUUID(), reportId: report.id, text: findingText.value.trim(), author: role.value.replaceAll('_', ' '), date: today(), classification: findingClass.value }); findingText.value = ''; report.status = 'Finding recorded'; flash('Classified finding recorded.') }
function addAction(report: Report) { if (!actionText.value.trim()) return; actions.value.unshift({ id: crypto.randomUUID(), reportId: report.id, text: actionText.value.trim(), status: 'OPEN' }); actionText.value = ''; flash('Follow-up action recorded.') }
function resetDemo() { if (!window.confirm('Reset all local synthetic demo activity?')) return; for (const key of ['civicproof-reports', 'civicproof-responses', 'civicproof-findings', 'civicproof-actions', 'civicproof-reviews']) localStorage.removeItem(key); reports.value = seededReports.map(report => ({ ...report, matches: [...report.matches], matchCandidates: [...report.matchCandidates] })); responses.value = []; findings.value = []; actions.value = []; reviews.value = []; navigate('Overview'); flash('Local synthetic demo activity reset.') }
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar"><button class="brand" @click="navigate(isCommunity ? 'My needs' : 'Overview')"><span class="brand-mark">C</span><span>Civic<strong>Proof</strong><small>PUBLIC ACCOUNTABILITY</small></span></button><div class="nav-caption">{{ isCommunity ? 'COMMUNITY SPACE' : 'STAFF DEMO WORKSPACE' }}</div><nav aria-label="Main navigation"><button v-for="item in menu" :key="item" :class="['nav-link',{active:activePage===item}]" @click="navigate(item)">{{ item }}<b v-if="item==='Match review'&&pendingMatches.length">{{ pendingMatches.length }}</b></button></nav><div class="sidebar-spacer"></div><div class="side-note"><strong>{{ isCommunity ? 'Your needs, your voice' : 'Community-led insight' }}</strong><p>{{ isCommunity ? 'Only submissions created by this demo member appear in your needs list.' : 'Reports are community-reported; suggestions are never proof.' }}</p><button @click="startReport">＋ Report a need</button></div><label class="role-select"><small>DEMO ROLE — NOT AUTHENTICATION</small><select v-model="role" aria-label="Switch demo role"><option v-for="item in roles" :key="item" :value="item">{{ item.replaceAll('_',' ') }}</option></select></label></aside>
    <main class="main-area"><header class="topbar"><div><span class="muted">Workspace</span><span class="slash">/</span><strong>{{ activePage }}</strong></div><span class="demo-tag">SYNTHETIC DEMO</span></header><div class="content">
      <template v-if="isCommunity"><div class="page-head"><div><div class="eyebrow">PRIVATE TO THIS DEMO PROFILE</div><h1>My community needs</h1><p>Report a need and follow the status of submissions you created.</p></div><button class="primary" @click="startReport">＋ Report a need</button></div><div class="notice-banner"><strong>Community view:</strong> other members’ reports, project details, match suggestions and staff investigation notes are not shown.</div><section v-if="reportDetail&&reportDetail.ownerId===memberId" class="panel detail"><button class="text-link" @click="activeReportId=null">← My needs</button><div class="eyebrow">YOUR SUBMISSION · {{ reportDetail.createdAt }}</div><h2>{{ reportDetail.title }}</h2><p>{{ reportDetail.description }}</p><div class="summary"><span>{{ categoryLabel(reportDetail.category) }}</span><span>{{ reportDetail.area }}</span><span class="status-pill">{{ reportDetail.status }}</span></div><p class="muted">Staff review details and project suggestions are not displayed in the community view.</p></section><section v-else class="panel"><div class="panel-heading"><div><div class="eyebrow">SUBMISSIONS YOU CREATED</div><h2>Your existing needs</h2></div><span class="count">{{ ownReports.length }}</span></div><button v-for="report in ownReports" :key="report.id" class="report-row" @click="openReport(report)"><span class="row-icon">＋</span><span class="row-main"><strong>{{ report.title }}</strong><small>{{ categoryLabel(report.category) }} · {{ report.area }} · {{ report.createdAt }}</small></span><span class="status-pill">{{ report.status }}</span></button><div v-if="!ownReports.length" class="empty">No needs submitted yet. Use “Report a need” to create one; it will appear here.</div></section></template>
      <template v-else-if="activePage==='Overview'"><div class="page-head"><div><div class="eyebrow">STAFF ROLE · {{ role.replaceAll('_',' ') }}</div><h1>Accountability workspace</h1><p>Review community submissions and support transparent follow-up.</p></div><button class="primary" @click="startReport">＋ Report a need</button></div><div class="notice-banner"><strong>Synthetic demo:</strong> records are fictional and the role selector is not authentication.</div><section class="stats"><article><span>Submissions</span><strong>{{ reports.length }}</strong></article><article><span>Projects</span><strong>{{ projects.length }}</strong></article><article><span>Open investigations</span><strong>{{ investigations.length }}</strong></article></section><section class="panel"><div class="panel-heading"><div><div class="eyebrow">LATEST SUBMISSIONS</div><h2>Recent community reports</h2></div><button class="text-link" @click="navigate('All submissions')">All submissions →</button></div><button v-for="report in reports.slice(0,5)" :key="report.id" class="report-row" @click="openReport(report)" :aria-label="`View submission: ${report.title}`"><span class="row-icon">＋</span><span class="row-main"><strong>{{ report.title }}</strong><small>{{ report.area }} · {{ categoryLabel(report.category) }} · {{ report.createdAt }}</small></span><span class="status-pill">{{ report.status }}</span><span aria-hidden="true">›</span></button></section></template>
      <template v-else-if="activePage==='All submissions'||activePage==='Responses'"><div class="page-head"><div><div class="eyebrow">{{ activePage==='Responses'?'DEPARTMENT FOLLOW-UP':'COMMUNITY SUBMISSIONS' }}</div><h1>{{ activePage==='Responses'?'Responses':'All submissions' }}</h1><p>Staff view of synthetic and locally created demo submissions.</p></div><button class="primary" @click="startReport">＋ Report a need</button></div><section v-if="reportDetail" class="panel detail"><button class="text-link" @click="activeReportId=null">← All submissions</button><span class="evidence-badge">COMMUNITY REPORTED</span><span class="status-pill">{{ reportDetail.status }}</span><h2>{{ reportDetail.title }}</h2><p>{{ reportDetail.description }}</p><div class="summary"><span>{{ categoryLabel(reportDetail.category) }}</span><span>{{ reportDetail.area }}</span><span>{{ reportDetail.createdAt }}</span></div><div class="caution">A community report is not independently verified. A suggested match is not proof of an allegation.</div><h3>Potential project records</h3><div v-for="id in reportDetail.matchCandidates" :key="id" class="candidate"><strong>{{ projects.find(project=>project.id===id)?.name }}</strong><small>{{ projects.find(project=>project.id===id)?.area }} · {{ projects.find(project=>project.id===id)?.status }}</small></div><p v-if="!reportDetail.matchCandidates.length" class="muted">No suggested project matches.</p><h3>Department responses</h3><article v-for="response in responses.filter(item=>item.reportId===reportDetail!.id)" :key="response.id" class="timeline"><strong>{{ response.author }}</strong><p>{{ response.text }}</p><small>{{ response.date }}</small></article><form v-if="role==='DEPARTMENT_OFFICIAL'||role==='ADMIN'" class="inline-form" @submit.prevent="addResponse(reportDetail!)"><textarea v-model="responseText" required placeholder="Record an acknowledgement or next step"></textarea><button class="primary">Record response</button></form></section><section v-else class="panel"><input v-model="search" class="search" placeholder="Search submissions"/><button v-for="report in shownReports" :key="report.id" class="report-row" @click="openReport(report)"><span class="row-icon">＋</span><span class="row-main"><strong>{{ report.title }}</strong><small>{{ report.area }} · {{ categoryLabel(report.category) }} · {{ report.createdAt }}</small></span><span class="status-pill">{{ report.status }}</span></button><div v-if="!shownReports.length" class="empty">No submissions found.</div></section></template>
      <template v-else-if="activePage==='Projects'"><div class="page-head"><div><div class="eyebrow">SYNTHETIC PUBLIC PROJECT REGISTER</div><h1>Projects</h1><p>Fictional demo records only; not municipal data.</p></div></div><section class="panel"><div class="filters"><input v-model="search" class="search" placeholder="Search projects or areas"/><select v-model="statusFilter"><option value="ALL">All statuses</option><option value="PLANNED">Planned</option><option value="IN_PROGRESS">In progress</option><option value="COMPLETED">Completed</option></select><select v-model="categoryFilter"><option value="ALL">All categories</option><option v-for="category in categoryOptions" :key="category" :value="category">{{ categoryLabel(category) }}</option></select></div><article v-for="project in shownProjects" :key="project.id" class="project-row"><strong>{{ project.name }}</strong><span>{{ project.area }} · {{ categoryLabel(project.category) }} · {{ project.status.replace('_',' ') }}</span><p>{{ project.description }}</p><small>{{ project.progress }}% progress · Synthetic demo record</small></article></section></template>
      <template v-else-if="activePage==='Match review'"><div class="page-head"><div><div class="eyebrow">HUMAN REVIEW REQUIRED</div><h1>Potential matches</h1><p>Confirmation opens follow-up; it does not verify the community report.</p></div></div><article v-for="item in pendingMatches" :key="`${item.report.id}-${item.project!.id}`" class="panel review-card"><span class="evidence-badge">COMMUNITY REPORTED</span><h2>{{ item.report.title }}</h2><p>{{ item.report.description }}</p><div class="candidate"><strong>{{ item.project!.name }}</strong><small>{{ item.project!.area }} · {{ item.project!.status }}</small></div><div class="actions"><button class="secondary" @click="decideMatch(item.report,item.project!,'REJECTED')">Reject suggestion</button><button class="primary" @click="decideMatch(item.report,item.project!,'CONFIRMED')">Confirm relationship</button></div></article><div v-if="!pendingMatches.length" class="empty">No suggested matches awaiting review.</div></template>
      <template v-else-if="activePage==='Investigations'"><div class="page-head"><div><div class="eyebrow">FOLLOW-UP AND EVIDENCE</div><h1>Investigations</h1><p>Community-need follow-up and project accountability are tracked separately.</p></div></div><section v-for="report in investigations" :key="report.id" class="panel investigation"><span class="status-pill">{{ report.investigationType?.replace('_',' ') }}</span><h2>{{ report.title }}</h2><p>{{ report.area }} · {{ report.status }}</p><article v-for="finding in findings.filter(item=>item.reportId===report.id)" :key="finding.id" class="timeline"><strong>{{ finding.classification.replaceAll('_',' ') }}</strong><p>{{ finding.text }}</p><small>{{ finding.date }} · {{ finding.author }}</small></article><form v-if="role==='INVESTIGATOR'||role==='ADMIN'" class="inline-form" @submit.prevent="addFinding(report)"><select v-model="findingClass"><option>COMMUNITY_REPORTED</option><option>SYSTEM_IDENTIFIED</option><option>OFFICIALLY_RECORDED</option><option>HUMAN_REVIEWED</option><option>INDEPENDENTLY_VERIFIED</option><option>OFFICIALLY_CONFIRMED</option></select><textarea v-model="findingText" required placeholder="Add a classified finding"></textarea><button class="primary">Record finding</button></form><h3>Corrective actions</h3><div v-for="action in actions.filter(item=>item.reportId===report.id)" :key="action.id" class="action-row"><span>{{ action.text }}</span><button class="status-pill" @click="action.status=action.status==='OPEN'?'COMPLETE':'OPEN'">{{ action.status }}</button></div><form v-if="role==='INVESTIGATOR'||role==='ADMIN'" class="inline-form" @submit.prevent="addAction(report)"><input v-model="actionText" required placeholder="Add a follow-up action"/><button class="secondary">＋ Add action</button></form></section><div v-if="!investigations.length" class="empty">No active investigations.</div></template>
      <template v-else-if="activePage==='Audit trail'"><div class="page-head"><div><div class="eyebrow">OVERSIGHT</div><h1>Audit trail</h1></div></div><section class="panel"><article v-for="item in reviews" :key="item.id" class="timeline"><strong>{{ item.decision }} · {{ reports.find(report=>report.id===item.reportId)?.title }}</strong><p>{{ item.reason }}</p></article><div v-if="!reviews.length" class="empty">No review actions recorded.</div></section></template>
      <template v-else><div class="page-head"><div><div class="eyebrow">LOCAL BROWSER DEMO</div><h1>Demo setup</h1></div></div><section class="panel"><h2>Data and privacy</h2><p>Community view shows only reports created by this demo member. The role switch is display-only, not authentication or access control.</p><button v-if="role==='ADMIN'" class="danger" @click="resetDemo">Reset local synthetic data</button></section></template>
    </div></main>
    <div v-if="modalOpen" class="overlay" @click.self="modalOpen=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="form-title"><button class="close" aria-label="Close" @click="modalOpen=false">×</button><div class="eyebrow">COMMUNITY SUBMISSION</div><h2 id="form-title">Report a community need</h2><p>No project ID or proof of residency is required.</p><form @submit.prevent="submitReport"><label>Type<select v-model="form.type"><option value="COMMUNITY_NEED">Community need</option><option value="SERVICE_OBSERVATION">Service observation</option></select></label><label>Title<input v-model="form.title" required minlength="3" maxlength="160"/></label><label>Category<select v-model="form.category"><option v-for="category in categoryOptions" :key="category" :value="category">{{ categoryLabel(category) }}</option></select></label><label>Description<textarea v-model="form.description" required minlength="10" maxlength="10000" rows="4"></textarea></label><label>Area<select v-model="form.area" required><option disabled value="">Choose an area</option><option v-for="area in areas" :key="area">{{ area }}</option></select></label><label>Nearby location<input v-model="form.location" required maxlength="200" placeholder="Street, landmark or nearby place"/></label><p class="muted">Saved locally in this browser demo; not sent to a government office.</p><button class="primary">Submit report</button></form></section></div>
    <div v-if="notice" class="toast" role="status">{{ notice }}<button aria-label="Dismiss" @click="notice=''">×</button></div><footer>CivicProof demo · Synthetic data · Role switching is not security · Reports are not independently verified</footer>
  </div>
</template>

